// Pure renderer for scenario-driven flow figures: flow JSON in, markup out.
// No DOM, no dependency, so it runs in node (Jekyll pre-render, tests) and in the
// browser (the <skraft-flow> element, the Docusaurus adapter) alike.
//
// The flow JSON is generated by eng/docs/flow-from-dot.mjs from a .skraft.dot workflow
// and a layout sidecar: geometry (node boxes, edge paths, chip positions) is already
// computed there, so this module only turns it into SVG and HTML.

const UI = {
  fr: {
    scenario: 'Scénario',
    replay: 'Rejouer',
    hint: 'Faites défiler le schéma horizontalement',
    alt: 'Version texte des scénarios',
    steps: 'Étapes',
  },
  en: {
    scenario: 'Scenario',
    replay: 'Replay',
    hint: 'Scroll the diagram sideways',
    alt: 'Text version of the scenarios',
    steps: 'Steps',
  },
}

// Fira Code advances 0.6 em; the generator uses the same metric to lay chips out.
export const MONO_ADVANCE = 0.6
export const CHIP_FONT = 10
export const chipWidth = (text) => Math.round(String(text).length * CHIP_FONT * MONO_ADVANCE + 12)

export const pick = (value, lang) =>
  value == null ? '' : typeof value === 'string' ? value : value[lang] ?? value.fr ?? value.en ?? ''

export const escapeHtml = (text) =>
  String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

/** Escape, then turn `code` spans into <code>. */
export const inline = (text) =>
  escapeHtml(text).replace(/`([^`]+)`/g, (_, code) => `<code>${code}</code>`)

const plain = (text) => String(text).replace(/`/g, '')

const ui = (lang) => UI[lang] ?? UI.fr

const attrs = (map) =>
  Object.entries(map)
    .filter(([, v]) => v !== undefined && v !== null && v !== false)
    .map(([k, v]) => (v === true ? k : `${k}="${escapeHtml(v)}"`))
    .join(' ')

function chipRow(label, chips, x0, y, width, lang) {
  // label ("in" / "out") then chips flowing left to right, wrapping under the first chip.
  const out = []
  const startX = label ? x0 + 25 : x0
  let x = startX
  let line = y
  if (label) out.push(`<text class="sf-node__io" x="${x0}" y="${line + 11.5}">${label}</text>`)
  for (const chip of chips) {
    const text = pick(chip, lang)
    const w = chipWidth(text)
    if (x > startX && x + w > width - 8) {
      x = startX
      line += 21
    }
    out.push(
      `<g class="sf-chip"><rect x="${x}" y="${line}" width="${w}" height="16" rx="8"/>` +
        `<text x="${x + w / 2}" y="${line + 11.5}">${escapeHtml(text)}</text></g>`,
    )
    x += w + 4
  }
  return { markup: out.join(''), next: line + 21 }
}

function renderNode(node, lang) {
  const cls = ['sf-node', `sf-node--${node.kind}`]
  if (node.tone) cls.push(`sf-node--${node.tone}`)
  const parts = []
  parts.push(`<rect class="sf-node__box" width="${node.w}" height="${node.h}" rx="8"/>`)
  if (node.io) {
    parts.push(`<text class="sf-node__iotitle" x="10" y="20">${escapeHtml(pick(node.title, lang))}</text>`)
    parts.push(chipRow('', node.chips ?? [], 10, 30, node.w, lang).markup)
  } else {
    parts.push(`<circle class="sf-node__badge" cx="17" cy="18" r="9.5"/>`)
    parts.push(`<text class="sf-node__num" x="17" y="21.5">${escapeHtml(node.badge ?? '')}</text>`)
    parts.push(`<text class="sf-node__title" x="32" y="23">${escapeHtml(node.id)}</text>`)
    if (node.mono) parts.push(`<text class="sf-node__mono" x="10" y="42">${escapeHtml(node.mono)}</text>`)
    let y = 52
    for (const [label, chips] of [['in', node.in], ['out', node.out]]) {
      if (!chips || chips.length === 0) continue
      const row = chipRow(label, chips, 10, y, node.w, lang)
      parts.push(row.markup)
      y = row.next
    }
  }
  return (
    `<g ${attrs({ class: cls.join(' '), 'data-node': node.id, 'data-io': node.io, transform: `translate(${node.x} ${node.y})` })}>` +
    `<g class="sf-node__body">${parts.join('')}</g></g>`
  )
}

function renderEdge(edge) {
  const tone = edge.tone ?? edge.kind
  const parts = [
    `<path ${attrs({ class: 'sf-edge__path', d: edge.d, 'marker-end': `url(#sf-arrow-${tone})` })}/>`,
  ]
  if (edge.chip) {
    const w = chipWidth(edge.chip.text) - 4
    parts.push(
      `<g class="sf-edge__chip"><rect x="${edge.chip.x - w / 2}" y="${edge.chip.y - 9}" width="${w}" height="18" rx="3"/>` +
        `<text x="${edge.chip.x}" y="${edge.chip.y + 3.5}">${escapeHtml(edge.chip.text)}</text></g>`,
    )
  }
  return `<g ${attrs({
    class: `sf-edge sf-edge--${edge.kind} sf-tone--${tone}`,
    'data-edge': edge.id,
    'data-from': edge.from,
    'data-to': edge.to,
  })}>${parts.join('')}</g>`
}

function renderLegend(legend, lang) {
  if (!legend) return ''
  const rows = legend.items.map((item, i) => {
    const y = 16 + i * 20
    const sample =
      item.kind === 'amber'
        ? `<rect class="sf-legend__card" x="0" y="${y - 6}" width="22" height="12" rx="3"/>`
        : `<path class="sf-legend__line sf-tone--${item.kind}" d="M0 ${y} H22"/>`
    return `${sample}<text x="30" y="${y + 4}">${escapeHtml(pick(item, lang))}</text>`
  })
  return `<g class="sf-legend" aria-hidden="true" transform="translate(${legend.x} ${legend.y})">${rows.join('')}</g>`
}

const MARKERS = ['flow', 'back', 'fail', 'amber']

/** The figure's SVG, as a string. */
export function render(flow, { lang = 'fr' } = {}) {
  const [w, h] = flow.viewBox
  const id = `sf-${flow.id}-${lang}`
  const title = pick(flow.title, lang)
  const desc = flow.scenarios
    .map((s) => `${pick(s.label, lang)} : ${s.path.join(' → ')}.`)
    .join(' ')
  const markers = MARKERS.map(
    (m) =>
      `<marker id="sf-arrow-${m}" class="sf-marker sf-tone--${m}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 1 L9 5 L0 9 z"/></marker>`,
  ).join('')
  return (
    `<svg class="sf-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" role="img" aria-labelledby="${id}-t ${id}-d">` +
    `<title id="${id}-t">${escapeHtml(title)}</title><desc id="${id}-d">${escapeHtml(desc)}</desc>` +
    `<defs>${markers}</defs>` +
    `<g class="sf-edges">${flow.edges.map(renderEdge).join('')}</g>` +
    `<g class="sf-nodes">${flow.nodes.map((n) => renderNode(n, lang)).join('')}</g>` +
    renderLegend(flow.legend, lang) +
    `</svg>`
  )
}

/** What the animation needs at runtime, embedded next to a pre-rendered figure. */
export const runtimeData = (flow) => ({
  id: flow.id,
  scenarios: flow.scenarios.map(({ id, label, caption, path, edges }) => ({ id, label, caption, path, edges })),
})

export const captionHtml = (scenario, lang) =>
  `<b>${escapeHtml(pick(scenario.label, lang))}</b> — ${inline(pick(scenario.caption, lang))}`

/** The whole <figure>: scenario bar, board with the SVG, caption, text alternative. */
export function renderFigure(flow, { lang = 'fr', embedData = true } = {}) {
  const t = ui(lang)
  const first = flow.scenarios[0]
  const buttons = flow.scenarios
    .map(
      (s, i) =>
        `<button type="button" class="sf-seg__btn" data-scenario="${escapeHtml(s.id)}" aria-pressed="${i === 0}">${escapeHtml(pick(s.label, lang))}</button>`,
    )
    .join('')
  const alt = flow.scenarios
    .map((s) => {
      const steps = s.path.map((node, i) => {
        const edge = i > 0 ? flow.edges.find((e) => e.id === s.edges[i - 1]) : null
        const verdict = edge?.label ? ` <span class="sf-alt__verdict">(${escapeHtml(edge.label)})</span>` : ''
        return `<li><code>${escapeHtml(node)}</code>${verdict}</li>`
      })
      return `<li><p>${captionHtml(s, lang)}</p><ol class="sf-alt__steps" aria-label="${t.steps}">${steps.join('')}</ol></li>`
    })
    .join('')
  const data = embedData
    ? `<script type="application/json" class="sf-data">${JSON.stringify(runtimeData(flow)).replace(/</g, '\\u003c')}</script>`
    : ''
  return [
    `<figure class="skraft-flow" data-flow="${escapeHtml(flow.id)}" data-lang="${lang}">`,
    `<div class="sf-bar" role="group" aria-label="${t.scenario}">`,
    `<span class="sf-bar__label" aria-hidden="true">${t.scenario}</span>`,
    `<div class="sf-seg">${buttons}</div>`,
    `<button type="button" class="sf-replay" aria-label="${t.replay}" title="${t.replay}"><span aria-hidden="true">↻</span></button>`,
    `</div>`,
    `<div class="sf-board" tabindex="0" aria-label="${escapeHtml(plain(pick(flow.title, lang)))}">${render(flow, { lang })}</div>`,
    `<p class="sf-hint" aria-hidden="true">${t.hint} →</p>`,
    `<p class="sf-caption" aria-live="polite">${captionHtml(first, lang)}</p>`,
    `<figcaption class="sf-figcaption">${inline(pick(flow.figcaption, lang))}</figcaption>`,
    `<details class="sf-alt"><summary>${t.alt}</summary><ul>${alt}</ul></details>`,
    data,
    `</figure>`,
  ].join('\n')
}
